/* The plugin window's core (gui_core.h). */
#include "gui_core.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "ui/frui_text.h"

/* the fonts, embedded in the binary (gui_fonts.c, generated by plugin/cmake/embed.cmake from assets/fonts) */
extern const unsigned char frp_font_text[], frp_font_display[];
extern const unsigned long frp_font_text_len, frp_font_display_len;
static frui_font *s_font, *s_dfont;  /* shared by every window of the process (main thread only) */
static int s_refs;

#define MAXDIRTY 12
#define PEND_S 0.6                   /* a value the window set is shown until the app has it, at most this long */
#define WHEEL_END_S 0.4              /* a wheel gesture ends after this pause */

enum { DR_NONE, DR_KNOB, DR_KEYS, DR_FADER };
enum { M_DOWN, M_DRAG, M_UP, M_MOVE, M_LEAVE, M_RDOWN };

struct frp_gui {
    frp_ui_host_t h;
    frui *u;
    frui_model m, drawn;             /* what to draw; what the canvas shows */
    int have_drawn, full;
    uint32_t *px;
    int pw, ph;
    uint32_t *st;                    /* the static layer at pw x ph (frui_set_layer): the plate, the section panels */
    int st_ok;
    float dr[MAXDIRTY][4];           /* logical rectangles to repaint */
    int nd;
    double now, last_tick;
    /* values the window set, shown until the app reports them */
    uint8_t pend_on[FRP_COUNT], pend_v[FRP_COUNT], pend_old[FRP_COUNT], app[FRP_COUNT];   /* app: its last value */
    double pend_t[FRP_COUNT];
    /* the drag */
    int drag, drag_id, drag_note;
    float drag_y, drag_x;
    double drag_v;
    /* the wheel's gesture */
    int wheel_id;
    double wheel_t;
    float wheel_acc;
    /* the window's own values when a backend is missing (frp_ui_iface.h) */
    int loc_tune, loc_fx, loc_set[8], loc_learning;
    uint8_t loc_learn[FRP_COUNT];
    int sustain_latch;
    /* the meter */
    float lvl[2], pk[2];
    double pk_t[2];
    uint8_t own_notes[128];          /* the keyboard's own notes (shown at once, before the app reports them) */
    /* the platform view (frp_gui_client) */
    frg_client cl;
    const uint32_t *tpx;             /* the view's buffer the canvas was last copied into */
    int tw, th;
};

/* ---- values */
static int hi_of(int id) { return frui_value_hi(id); }
static int clampi(int v, int lo, int hi) { return v < lo ? lo : v > hi ? hi : v; }

static int setting_get(frp_gui_t *g, int key, int def_local)
{
    int v;
    if (g->h.setting_get && g->h.setting_get(g->h.ctx, key, &v) == 0) return v;
    return def_local;
}
static int *loc_setting(frp_gui_t *g, int key)
{
    if (key >= FRS_CHANNEL && key <= FRS_SYNCDIV) return &g->loc_set[key - FRS_CHANNEL];
    if (key == FRP_UI_TUNE) return &g->loc_tune;
    if (key == FRP_UI_FX_BYPASS) return &g->loc_fx;
    return 0;
}
static void setting_set(frp_gui_t *g, int key, int v)
{
    int *l = loc_setting(g, key);
    if (l) *l = v;
    if (g->h.setting_set) g->h.setting_set(g->h.ctx, key, v);
}
static void gesture(frp_gui_t *g, int id, int begin)
{
    if (id == FRP_TW_KIND) { gesture(g, FRP_TW_SW, begin); gesture(g, FRP_TW_MODE, begin); return; }
    if (id >= 0 && id < FRP_COUNT && g->h.param_gesture) g->h.param_gesture(g->h.ctx, (uint32_t)id, begin);
}
static void param_set(frp_gui_t *g, int id, int v)
{
    v = clampi(v, 0, hi_of(id));
    if (!g->pend_on[id]) g->pend_old[id] = g->app[id];
    g->pend_on[id] = 1; g->pend_v[id] = (uint8_t)v; g->pend_t[id] = g->now;
    g->m.p[id] = (uint8_t)v;
    if (g->h.param_set) g->h.param_set(g->h.ctx, (uint32_t)id, (double)v);
}
/* a control's value from the window (inside a gesture when it is a parameter) */
static void set_value(frp_gui_t *g, int id, int v)
{
    v = clampi(v, 0, hi_of(id));
    if (id == FRP_TW_KIND) {                         /* OFF PAN TREM WAH: the device's TW_SW + TW_MODE */
        param_set(g, FRP_TW_SW, v == 0 ? 0 : v == 3 ? 2 : 1);
        if (v == 1 || v == 2) param_set(g, FRP_TW_MODE, v == 2);
    } else if (id >= 0 && id < FRP_COUNT) param_set(g, id, v);
    else if (id == FRP_TUNE) { setting_set(g, FRP_UI_TUNE, v - 50); g->m.tune = v - 50; }
    else if (id >= FRS_CHANNEL && id <= FRS_SYNCDIV) {
        setting_set(g, id, id == FRS_BPM ? v : v);
        frp_gui_tick(g, g->now);
    }
}
static void set_once(frp_gui_t *g, int id, int v)
{
    gesture(g, id, 1);
    set_value(g, id, v);
    gesture(g, id, 0);
}
static int default_of(frp_gui_t *g, int id)
{
    if (id >= 0 && id < FRP_COUNT)
        return g->h.param_default ? (int)floor(g->h.param_default(g->h.ctx, (uint32_t)id) + 0.5) : frui_param_def[id];
    if (id == FRP_TUNE) return 50;
    if (id == FRS_FIXVEL) return 100;
    return 0;
}
static void midi(frp_gui_t *g, uint8_t st, uint8_t d1, uint8_t d2)
{
    int ch = g->m.midi_ch > 0 ? g->m.midi_ch - 1 : 0;   /* the window plays on the channel the app listens to */
    if (g->h.midi) g->h.midi(g->h.ctx, (uint8_t)(st | ch), d1, d2);
}
static void note(frp_gui_t *g, int key, int vel)
{
    if (key < 0 || key > 127) return;
    g->own_notes[key] = (uint8_t)vel;
    midi(g, vel ? 0x90 : 0x80, (uint8_t)key, (uint8_t)(vel ? vel : 64));
}

/* ---- the dirty rectangles */
static void dirty(frp_gui_t *g, float x, float y, float w, float h)
{
    if (w <= 0.f || h <= 0.f) return;
    if (g->nd >= MAXDIRTY) { g->full = 1; return; }
    g->dr[g->nd][0] = x - 4.f; g->dr[g->nd][1] = y - 4.f; g->dr[g->nd][2] = w + 8.f; g->dr[g->nd][3] = h + 8.f;
    g->nd++;
}
static void dirty_region(frp_gui_t *g, int which)
{
    float r[4];
    frui_region(g->u, which, r);
    if (r[2] > 0.f) dirty(g, r[0], r[1], r[2], r[3]); else g->full = 1;
}
static void dirty_wid(frp_gui_t *g, int wid)        /* every widget with this id (a knob, its menu ...) */
{
    int i, n = frui_widget_count(g->u);
    if (wid < 0) return;
    for (i = 0; i < n; i++) {
        const frui_widget *w = frui_widget_get(g->u, i);
        if (FRUI_WID(w->kind, w->id) == wid) dirty(g, w->x, w->y, w->w, w->h);
    }
}
static void dirty_param(frp_gui_t *g, int id)
{
    int i, n = frui_widget_count(g->u), found = 0;
    if (hi_of(id) != 127 || id == FRP_LEVEL) {        /* a switch, a type, a sync: other controls follow it */
        if (id == FRP_LEVEL) { dirty_region(g, FRR_RAIL); return; }
        g->full = 1;
        return;
    }
    for (i = 0; i < n; i++) {
        const frui_widget *w = frui_widget_get(g->u, i);
        if (w->kind == FRW_KNOB && w->id == id) { dirty(g, w->x, w->y, w->w, w->h); found = 1; }
    }
    (void)found;
    switch (id) {                                    /* the values that light a tab's lamp or draw a curve */
    case FRP_EQ_LO: case FRP_EQ_MID: case FRP_EQ_FREQ: case FRP_EQ_HI: case FRP_DRIVE: dirty_region(g, FRR_PANEL_L); break;
    case FRP_FL_FREQ: case FRP_FL_RESO: case FRP_FL_LFO: dirty_region(g, FRR_PANEL_R); break;
    }
}
static void diff(frp_gui_t *g)
{
    const frui_model *a = &g->drawn, *b = &g->m;
    int i;
    if (!g->have_drawn) { g->full = 1; return; }
    for (i = 0; i < FRP_COUNT; i++) if (a->p[i] != b->p[i]) dirty_param(g, i);
    if (a->tune != b->tune) dirty_wid(g, FRUI_WID(FRW_KNOB, FRP_TUNE));
    if (memcmp(a->out_db, b->out_db, sizeof a->out_db) || memcmp(a->out_peak_db, b->out_peak_db, sizeof a->out_peak_db))
        dirty_region(g, FRR_METER);
    if (a->gr_db != b->gr_db) { float r[4]; frui_region(g->u, FRR_GR, r); if (r[2] > 0.f) dirty(g, r[0], r[1], r[2], r[3]); }
    if (memcmp(a->notes, b->notes, sizeof a->notes)) {
        float r[4], x0 = 1e9f, x1 = -1e9f;
        frui_region(g->u, FRR_KEYS, r);
        for (i = 24; i <= 84; i++)
            if ((a->notes[i] != 0) != (b->notes[i] != 0)) {
                float k0, k1;
                frui_key_span(i, &k0, &k1);
                if (k0 - 8.f < x0) x0 = k0 - 8.f;    /* (a white key's neighbours' black keys overlap it) */
                if (k1 + 8.f > x1) x1 = k1 + 8.f;
            }
        if (x1 > x0 && r[2] > 0.f) dirty(g, x0, r[1], x1 - x0, r[3]);
    }
    if (a->sustain != b->sustain) dirty_wid(g, FRUI_WID(FRW_BUTTON, FRB_SUSTAIN));
    if (a->fx_bypass != b->fx_bypass) g->full = 1;
    if (a->hover != b->hover) { dirty_wid(g, a->hover); dirty_wid(g, b->hover); }
    if (a->focus != b->focus) { dirty_wid(g, a->focus); dirty_wid(g, b->focus); }
    /* everything else changes the layout or many places at once */
    if (strcmp(a->preset_tag, b->preset_tag) || strcmp(a->preset_name, b->preset_name) || a->edited != b->edited ||
        a->tab_l != b->tab_l || a->tab_r != b->tab_r || a->page_rv != b->page_rv || a->menu != b->menu ||
        a->ctx_knob != b->ctx_knob || a->learning != b->learning || memcmp(a->learn_cc, b->learn_cc, sizeof a->learn_cc) ||
        a->settings != b->settings || a->midi_ch != b->midi_ch || a->vel_curve != b->vel_curve ||
        a->fixed_vel != b->fixed_vel || a->pgm_change != b->pgm_change || a->tempo_src != b->tempo_src ||
        a->bpm10 != b->bpm10 || a->host_bpm10 != b->host_bpm10 || a->sync_all != b->sync_all ||
        a->sync_div != b->sync_div || a->cc_scroll != b->cc_scroll)
        g->full = 1;
}

/* ---- the model from the app */
static float q_db(float db) { return db < -60.f ? -60.f : floorf(db * 2.f + 0.5f) * 0.5f; }
int frp_gui_tick(frp_gui_t *g, double now)
{
    frui_model *m = &g->m;
    frp_ui_monitor_t mon;
    double dt = g->last_tick > 0.0 ? now - g->last_tick : 0.0;
    int i;
    g->now = now;
    g->last_tick = now;
    if (dt < 0.0 || dt > 1.0) dt = 0.0;
    for (i = 0; i < FRP_COUNT; i++) {
        double v;
        int iv;
        if (!g->h.param_get || g->h.param_get(g->h.ctx, (uint32_t)i, &v)) continue;
        iv = clampi((int)floor(v + 0.5), 0, hi_of(i));
        g->app[i] = (uint8_t)iv;
        if (g->pend_on[i]) {             /* held until the app has it, something else moves it, or PEND_S */
            int dragging = (g->drag == DR_KNOB && g->drag_id == i) || g->wheel_id == i;
            if (dragging) iv = g->pend_v[i];
            else if (iv == g->pend_v[i] || iv != g->pend_old[i] || now - g->pend_t[i] > PEND_S) g->pend_on[i] = 0;
            else iv = g->pend_v[i];
        }
        m->p[i] = (uint8_t)iv;
    }
    m->tune = clampi(setting_get(g, FRP_UI_TUNE, g->loc_tune), -50, 50);
    m->fx_bypass = setting_get(g, FRP_UI_FX_BYPASS, g->loc_fx) != 0;
    m->midi_ch = setting_get(g, FRS_CHANNEL, g->loc_set[FRS_CHANNEL - FRS_CHANNEL]);
    m->vel_curve = setting_get(g, FRS_VEL, g->loc_set[FRS_VEL - FRS_CHANNEL]);
    m->fixed_vel = setting_get(g, FRS_FIXVEL, g->loc_set[FRS_FIXVEL - FRS_CHANNEL]);
    m->pgm_change = setting_get(g, FRS_PGM, g->loc_set[FRS_PGM - FRS_CHANNEL]);
    m->tempo_src = setting_get(g, FRS_TEMPO, g->loc_set[FRS_TEMPO - FRS_CHANNEL]);
    m->bpm10 = setting_get(g, FRS_BPM, g->loc_set[FRS_BPM - FRS_CHANNEL]);
    m->host_bpm10 = setting_get(g, FRP_UI_HOST_BPM10, m->bpm10);
    m->sync_all = setting_get(g, FRS_SYNCALL, g->loc_set[FRS_SYNCALL - FRS_CHANNEL]);
    m->sync_div = setting_get(g, FRS_SYNCDIV, g->loc_set[FRS_SYNCDIV - FRS_CHANNEL]);
    if (g->h.preset) {
        char tag[8] = "", name[24] = "";
        int ed = 0;
        g->h.preset(g->h.ctx, tag, name, &ed);
        memcpy(m->preset_tag, tag, sizeof tag); m->preset_tag[7] = 0;
        memcpy(m->preset_name, name, sizeof name); m->preset_name[23] = 0;
        m->edited = ed;
    }
    if (g->h.learn_get) g->h.learn_get(g->h.ctx, m->learn_cc, FRP_COUNT, &m->learning);
    else { memcpy(m->learn_cc, g->loc_learn, sizeof m->learn_cc); m->learning = g->loc_learning; }
    memset(&mon, 0, sizeof mon);
    if (g->h.monitor) g->h.monitor(g->h.ctx, &mon);
    for (i = 0; i < 128; i++) m->notes[i] = mon.notes[i] ? mon.notes[i] : g->own_notes[i];
    m->sustain = mon.sustain || g->sustain_latch;
    m->gr_db = floorf(mon.gr_db * 10.f + 0.5f) / 10.f;
    for (i = 0; i < 2; i++) {                        /* the meter: falls 24 dB/s; the peak holds 1.5 s, then falls */
        float db = mon.peak[i] > 1e-6f ? 20.f * log10f(mon.peak[i]) : -120.f;
        g->lvl[i] = fmaxf(db, g->lvl[i] - 24.f * (float)dt);
        if (db >= g->pk[i]) { g->pk[i] = db; g->pk_t[i] = now; }
        else if (now - g->pk_t[i] > 1.5) g->pk[i] -= 20.f * (float)dt;
        if (g->lvl[i] < -60.f) g->lvl[i] = -60.f;
        if (g->pk[i] < -60.f) g->pk[i] = -60.f;
        m->out_db[i] = q_db(g->lvl[i]);
        m->out_peak_db[i] = q_db(g->pk[i]);
    }
    if (g->wheel_id >= 0 && now - g->wheel_t > WHEEL_END_S) { gesture(g, g->wheel_id, 0); g->wheel_id = -1; }
    diff(g);
    return g->full || g->nd > 0;
}

/* ---- painting */
int frp_gui_resize(frp_gui_t *g, int pw, int ph)
{
    int w = pw, h = (int)((long)pw * FRUI_H / FRUI_W);
    uint32_t *px;
    if (h > ph) { h = ph; w = (int)((long)ph * FRUI_W / FRUI_H); }
    if (w < 16 || h < 10) { w = 16; h = 10; }
    if (w == g->pw && h == g->ph && g->px) return 0;
    px = malloc(sizeof(uint32_t) * (size_t)w * (size_t)h);
    if (!px) return -1;
    free(g->px);
    free(g->st);
    g->px = px; g->pw = w; g->ph = h;
    g->st = malloc(sizeof(uint32_t) * (size_t)w * (size_t)h);
    g->st_ok = 0;
    g->full = 1;
    return g->st ? 0 : -1;
}
int frp_gui_paint(frp_gui_t *g, int d[4])
{
    frui_canvas c;
    float s;
    int i;
    if (!g->px) return 0;
    if (!g->full && !g->nd) return 0;
    if (!g->st_ok) {                                 /* the static layer, once per size */
        frui_canvas_init(&c, g->st, g->pw, g->ph);
        frui_set_layer(g->u, FRUI_LAYER_STATIC);
        frui_draw(g->u, &g->m, &c);
        frui_set_layer(g->u, FRUI_LAYER_DYNAMIC);
        g->st_ok = 1;
        g->full = 1;
    }
    frui_canvas_init(&c, g->px, g->pw, g->ph);
    s = (float)g->pw / (float)FRUI_W;
    if (!g->full) {                                  /* many small rectangles: one full paint is cheaper */
        float area = 0.f;
        for (i = 0; i < g->nd; i++) area += g->dr[i][2] * g->dr[i][3];
        if (area > 0.4f * (float)(FRUI_W * FRUI_H)) g->full = 1;
    }
    if (g->full) {
        memcpy(g->px, g->st, sizeof(uint32_t) * (size_t)g->pw * (size_t)g->ph);
        frui_draw(g->u, &g->m, &c);
        d[0] = 0; d[1] = 0; d[2] = g->pw; d[3] = g->ph;
    } else {
        d[0] = g->pw; d[1] = g->ph; d[2] = 0; d[3] = 0;
        for (i = 0; i < g->nd; i++) {
            int x0 = (int)floorf(g->dr[i][0] * s), y0 = (int)floorf(g->dr[i][1] * s);
            int x1 = (int)ceilf((g->dr[i][0] + g->dr[i][2]) * s), y1 = (int)ceilf((g->dr[i][1] + g->dr[i][3]) * s);
            x0 = clampi(x0, 0, g->pw); x1 = clampi(x1, 0, g->pw); y0 = clampi(y0, 0, g->ph); y1 = clampi(y1, 0, g->ph);
            if (x1 <= x0 || y1 <= y0) continue;
            for (int y = y0; y < y1; y++)
                memcpy(g->px + (size_t)y * (size_t)g->pw + (size_t)x0, g->st + (size_t)y * (size_t)g->pw + (size_t)x0,
                       sizeof(uint32_t) * (size_t)(x1 - x0));
            frui_clip_base(&c, x0, y0, x1, y1);
            frui_draw(g->u, &g->m, &c);
            if (x0 < d[0]) d[0] = x0;
            if (y0 < d[1]) d[1] = y0;
            if (x1 > d[2]) d[2] = x1;
            if (y1 > d[3]) d[3] = y1;
        }
    }
    g->drawn = g->m;
    g->have_drawn = 1;
    g->full = 0;
    g->nd = 0;
    return d[2] > d[0] && d[3] > d[1];
}
const uint32_t *frp_gui_pixels(const frp_gui_t *g, int *w, int *h)
{
    *w = g->pw; *h = g->ph;
    return g->px;
}
const frui_model *frp_gui_model(const frp_gui_t *g) { return &g->m; }
const frui *frp_gui_frui(const frp_gui_t *g) { return g->u; }
int frp_gui_find(const frp_gui_t *g, int kind, int id, float r[4])
{
    int i, n = frui_widget_count(g->u);
    for (i = 0; i < n; i++) {
        const frui_widget *w = frui_widget_get(g->u, i);
        if (w->kind == kind && w->id == id) { r[0] = w->x; r[1] = w->y; r[2] = w->w; r[3] = w->h; return 1; }
    }
    return 0;
}
float frp_gui_px_to_logical(const frp_gui_t *g) { return g->pw > 0 ? (float)FRUI_W / (float)g->pw : 1.f; }
void frp_gui_fit_size(uint32_t *w, uint32_t *h)
{
    uint32_t a = *w, b = *h;
    /* the larger of the two sizes the request allows, as a host drags either edge */
    uint32_t ww = a, wh = (uint32_t)((uint64_t)b * FRUI_W / FRUI_H);
    if (wh < ww) ww = wh;
    if (ww < FRP_GUI_MIN_W) ww = FRP_GUI_MIN_W;
    if (ww > FRP_GUI_MAX_W) ww = FRP_GUI_MAX_W;
    *w = ww;
    *h = (uint32_t)((ww * FRUI_H + FRUI_W / 2) / FRUI_W);
}

/* ---- input */
static int hit(frp_gui_t *g, float x, float y, frui_widget *w) { return frui_hit(g->u, x, y, w) >= 0; }
static void close_popups(frp_gui_t *g) { g->m.menu = -1; g->m.ctx_knob = -1; }
static void learn(frp_gui_t *g, int cmd, int id)
{
    if (g->h.learn_cmd) { g->h.learn_cmd(g->h.ctx, cmd, id); return; }
    switch (cmd) {                                   /* (no backend: shown only; nothing listens for the CC) */
    case FRP_UI_LEARN_START: g->loc_learning = id; break;
    case FRP_UI_LEARN_CANCEL: g->loc_learning = -1; break;
    case FRP_UI_LEARN_FORGET: if (id >= 0 && id < FRP_COUNT) g->loc_learn[id] = 0; break;
    default: memset(g->loc_learn, 0, sizeof g->loc_learn); g->loc_learning = -1; break;
    }
}
static int vel_at(float y) { return clampi(40 + (int)((y - 504.f) / 80.f * 100.f), 1, 127); }
static void button(frp_gui_t *g, int id)
{
    frui_model *m = &g->m;
    switch (id) {
    case FRB_PREV: case FRB_NEXT: case FRB_SAVE: case FRB_UNDO:
        if (g->h.preset_cmd)
            g->h.preset_cmd(g->h.ctx, id == FRB_PREV ? FRP_UI_PRESET_PREV : id == FRB_NEXT ? FRP_UI_PRESET_NEXT :
                                      id == FRB_SAVE ? FRP_UI_PRESET_SAVE : FRP_UI_PRESET_UNDO);
        break;
    case FRB_TYPE_PREV: set_once(g, FRP_TYPE, (m->p[FRP_TYPE] + 5) % 6); break;
    case FRB_TYPE_NEXT: set_once(g, FRP_TYPE, (m->p[FRP_TYPE] + 1) % 6); break;
    case FRB_GEAR: m->settings = !m->settings; close_popups(g); break;
    case FRB_CLOSE: m->settings = 0; close_popups(g); break;
    case FRB_SUSTAIN:                                /* latching, as the device's REC: CC 64 down / up */
        g->sustain_latch = !g->sustain_latch;
        midi(g, 0xB0, 64, g->sustain_latch ? 127 : 0);
        break;
    case FRB_FX:                                     /* every effect bypassed (the app's CC 111, the FX button's) */
        if (g->h.setting_set) setting_set(g, FRP_UI_FX_BYPASS, !m->fx_bypass);
        else { g->loc_fx = !m->fx_bypass; midi(g, 0xB0, 111, g->loc_fx ? 127 : 0); }
        m->fx_bypass = !m->fx_bypass;
        break;
    case FRB_BPM_DOWN: case FRB_BPM_UP:
        if (m->tempo_src == 1) setting_set(g, FRS_BPM, clampi(m->bpm10 + (id == FRB_BPM_UP ? 10 : -10), 200, 3000));
        break;
    case FRB_LEARN_RESET: learn(g, FRP_UI_LEARN_FORGET_ALL, -1); break;
    }
}
static int focusable(const frui_widget *w)
{
    return w->kind == FRW_KNOB || w->kind == FRW_SEG || w->kind == FRW_MENU || (w->kind == FRW_FADER && w->id == FRS_FIXVEL);
}
static void step_value(frp_gui_t *g, int id, int dir, int mods)
{
    int hi = hi_of(id), st = hi >= 100 && (mods & FRG_SHIFT) ? 10 : 1;
    if (id == FRS_BPM) { if (g->m.tempo_src == 1) setting_set(g, FRS_BPM, clampi(g->m.bpm10 + dir * st * 10, 200, 3000)); return; }
    set_once(g, id, clampi(frui_value(&g->m, id) + dir * st, 0, hi));
}

static void mouse(frp_gui_t *g, int ev, float x, float y, int mods, int clicks)
{
    frui_model *m = &g->m;
    frui_widget w;
    int on = hit(g, x, y, &w);
    switch (ev) {
    case M_MOVE: case M_LEAVE:
        m->hover = ev == M_MOVE && on && w.kind != FRW_KEYS && w.kind != FRW_CCMAP ? FRUI_WID(w.kind, w.id) : -1;
        return;
    case M_RDOWN:
        close_popups(g);
        if (on && w.kind == FRW_KNOB && w.id < FRP_COUNT) m->ctx_knob = w.id;
        return;
    case M_DOWN:
        if (m->menu >= 0) {                          /* an open menu: an item, or a click anywhere closes it */
            int id = m->menu & 0xFF, kind = m->menu >> 8;
            if (on && w.kind == FRW_ITEM && kind == FRW_MENU) set_once(g, id, w.id);
            m->menu = -1;
            return;
        }
        if (m->ctx_knob >= 0) {                      /* the knob's menu */
            int id = m->ctx_knob;
            m->ctx_knob = -1;
            if (on && w.kind == FRW_CTX) {
                if (w.id == FRC_LEARN) learn(g, m->learning == id ? FRP_UI_LEARN_CANCEL : FRP_UI_LEARN_START, id);
                else if (w.id == FRC_FORGET) learn(g, FRP_UI_LEARN_FORGET, id);
                else set_once(g, id, default_of(g, id));
            }
            return;
        }
        if (m->learning >= 0) learn(g, FRP_UI_LEARN_CANCEL, m->learning);   /* any other click ends a MIDI learn */
        if (!on) { m->focus = -1; return; }
        switch (w.kind) {
        case FRW_KNOB:
            m->focus = FRUI_WID(w.kind, w.id);
            if (clicks >= 2 || (mods & (FRG_CMD | FRG_CTRL))) { set_once(g, w.id, default_of(g, w.id)); return; }
            g->drag = DR_KNOB; g->drag_id = w.id; g->drag_y = y; g->drag_v = frui_value(m, w.id);
            gesture(g, w.id, 1);
            return;
        case FRW_SEG:
            m->focus = FRUI_WID(w.kind, w.id);
            set_once(g, w.id, frui_seg_at(&w, x));
            return;
        case FRW_MENU:
            m->focus = FRUI_WID(w.kind, w.id);
            m->menu = FRUI_WID(w.kind, w.id);
            return;
        case FRW_TAB_L: m->tab_l = w.id; return;
        case FRW_TAB_R: m->tab_r = w.id; return;
        case FRW_PAGER: m->page_rv = x >= w.x + w.w * 0.5f; return;
        case FRW_BUTTON: button(g, w.id); return;
        case FRW_KEYS: {
            int k = frui_key_at(x, y);
            if (k < 0) return;
            note(g, k, vel_at(y));
            g->drag = DR_KEYS; g->drag_note = k;
            return;
        }
        case FRW_FADER:
            if (w.id == FRS_FIXVEL) {
                m->focus = FRUI_WID(w.kind, w.id);
                set_value(g, FRS_FIXVEL, clampi(1 + (int)((x - w.x) / w.w * 127.f), 1, 127));
                g->drag = DR_FADER; g->drag_id = w.id; g->drag_x = w.x; g->drag_v = w.w;
            } else if (w.id == FRS_BPM && m->tempo_src == 1) {
                g->drag = DR_KNOB; g->drag_id = FRS_BPM; g->drag_y = y; g->drag_v = m->bpm10;
            }
            return;
        default: return;
        }
    case M_DRAG:
        if (g->drag == DR_KNOB) {
            /* 200 logical px for the whole range; shift: ten times finer (from where shift went down) */
            int id = g->drag_id, hi = id == FRS_BPM ? 2800 : hi_of(id), v;
            double k = (double)hi / 200.0 * (mods & FRG_SHIFT ? 0.1 : 1.0), lo = id == FRS_BPM ? 200.0 : 0.0;
            double top = id == FRS_BPM ? 3000.0 : (double)hi;
            g->drag_v += (double)(g->drag_y - y) * k;
            if (g->drag_v < lo) g->drag_v = lo;
            if (g->drag_v > top) g->drag_v = top;
            g->drag_y = y;
            v = (int)floor(g->drag_v + 0.5);
            if (id == FRS_BPM) { if (v != m->bpm10) setting_set(g, FRS_BPM, v); }
            else if (v != frui_value(m, id)) set_value(g, id, v);
        } else if (g->drag == DR_KEYS) {
            int k = frui_key_at(x, y);
            if (k != g->drag_note) {
                note(g, g->drag_note, 0);
                if (k >= 0) note(g, k, vel_at(y));
                g->drag_note = k;
            }
        } else if (g->drag == DR_FADER) {
            set_value(g, FRS_FIXVEL, clampi(1 + (int)((x - g->drag_x) / (float)g->drag_v * 127.f), 1, 127));
        }
        return;
    case M_UP:
        if (g->drag == DR_KNOB && g->drag_id != FRS_BPM) gesture(g, g->drag_id, 0);
        if (g->drag == DR_KEYS) note(g, g->drag_note, 0);
        g->drag = DR_NONE;
        return;
    }
}
static void wheel(frp_gui_t *g, float x, float y, float notches, int mods)
{
    frui_widget w;
    int steps, id, hi;
    if (!hit(g, x, y, &w)) return;
    if (w.kind == FRW_CCMAP) {
        g->wheel_acc += notches;
        steps = (int)g->wheel_acc;
        g->wheel_acc -= (float)steps;
        g->m.cc_scroll = clampi(g->m.cc_scroll - steps, 0, 200);
        return;
    }
    if (w.kind != FRW_KNOB && w.kind != FRW_SEG && w.kind != FRW_MENU) return;
    id = w.id; hi = hi_of(id);
    g->wheel_acc += notches * (hi >= 100 && !(mods & FRG_SHIFT) ? 2.f : 1.f);
    steps = (int)g->wheel_acc;
    g->wheel_acc -= (float)steps;
    if (!steps) return;
    if (g->wheel_id != id) {
        if (g->wheel_id >= 0) gesture(g, g->wheel_id, 0);
        g->wheel_id = id;
        gesture(g, id, 1);
    }
    g->wheel_t = g->now;
    set_value(g, id, clampi(frui_value(&g->m, id) + steps, 0, hi));
}
static int on_key(frp_gui_t *g, int key, int mods)
{
    frui_model *m = &g->m;
    int i, n = frui_widget_count(g->u), cur = -1, fid;
    switch (key) {
    case FRK_ESCAPE:
        if (m->menu >= 0 || m->ctx_knob >= 0) { close_popups(g); return 1; }
        if (m->learning >= 0) { learn(g, FRP_UI_LEARN_CANCEL, m->learning); return 1; }
        if (m->settings) { m->settings = 0; return 1; }
        if (m->focus >= 0) { m->focus = -1; return 1; }
        return 0;
    case FRK_TAB:                                /* the next control in reading order (the draw's order) */
        for (i = 0; i < n; i++) if (FRUI_WID(frui_widget_get(g->u, i)->kind, frui_widget_get(g->u, i)->id) == m->focus) cur = i;
        for (i = 1; i <= n; i++) {
            int j = ((cur < 0 ? (mods & FRG_SHIFT ? 0 : -1) : cur) + (mods & FRG_SHIFT ? -i : i) + 2 * n) % n;
            const frui_widget *w = frui_widget_get(g->u, j);
            if (focusable(w)) { m->focus = FRUI_WID(w->kind, w->id); close_popups(g); return 1; }
        }
        return 1;
    }
    if (m->focus < 0) return 0;
    fid = m->focus & 0xFF;
    switch (key) {
    case FRK_UP: case FRK_RIGHT: step_value(g, fid, 1, mods); return 1;
    case FRK_DOWN: case FRK_LEFT: step_value(g, fid, -1, mods); return 1;
    case FRK_PGUP: case FRK_PGDN:
        step_value(g, fid, key == FRK_PGUP ? 1 : -1, hi_of(fid) >= 100 ? FRG_SHIFT : 0);
        return 1;
    case FRK_HOME: set_once(g, fid, 0); return 1;
    case FRK_END: set_once(g, fid, hi_of(fid)); return 1;
    case FRK_DELETE: case FRK_BACKSPACE: set_once(g, fid, default_of(g, fid)); return 1;
    case FRK_RETURN:
        if ((m->focus >> 8) == FRW_MENU) { m->menu = m->menu == m->focus ? -1 : m->focus; return 1; }
        if ((m->focus >> 8) == FRW_SEG) { set_once(g, fid, (frui_value(m, fid) + 1) % (hi_of(fid) + 1)); return 1; }
        return 0;
    }
    return 0;
}

static double mono_now(void)
{
    struct timespec ts;
    timespec_get(&ts, TIME_UTC);
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}
static void focus_lost(frp_gui_t *g)
{
    if (g->drag == DR_KNOB && g->drag_id != FRS_BPM) gesture(g, g->drag_id, 0);
    if (g->drag == DR_KEYS) note(g, g->drag_note, 0);
    g->drag = DR_NONE;
    if (g->wheel_id >= 0) { gesture(g, g->wheel_id, 0); g->wheel_id = -1; }
}
int frp_gui_input(frp_gui_t *g, const frg_input *e)
{
    frui_model before = g->m;
    float x = e->x, y = e->y;
    int used = 2;
    if (g->tw > 0 && g->pw > 0 && g->tw != g->pw) {  /* (a view wider than 16:10: the window is narrower than it) */
        x *= (float)g->tw / (float)g->pw;
        y *= (float)g->tw / (float)g->pw;
    }
    if (e->kind == FRG_DOWN || e->kind == FRG_DOUBLE || e->kind == FRG_WHEEL || e->kind == FRG_KEY)
        frp_gui_tick(g, mono_now());                 /* (the values as they are now, not as of the last tick) */
    switch (e->kind) {
    case FRG_DOWN: case FRG_DOUBLE:
        focus_lost(g);                               /* (a drag without its release, a wheel gesture: ended) */
        if (e->button == FRG_RIGHT) mouse(g, M_RDOWN, x, y, e->mods, 1);
        else if (e->button == FRG_LEFT) mouse(g, M_DOWN, x, y, e->mods, e->kind == FRG_DOUBLE ? 2 : 1);
        else used = 0;
        break;
    case FRG_UP: if (e->button == FRG_LEFT) mouse(g, M_UP, x, y, e->mods, 1); break;
    case FRG_MOVE:
        if (g->drag != DR_NONE) mouse(g, M_DRAG, x, y, e->mods, 1);
        else { mouse(g, M_MOVE, x, y, e->mods, 1); used = 0; }  /* (a hover: a repaint only if it changed) */
        break;
    case FRG_LEAVE: if (g->drag == DR_NONE) mouse(g, M_LEAVE, x, y, e->mods, 1); used = 0; break;
    case FRG_WHEEL: wheel(g, x, y, e->wheel, e->mods); break;
    case FRG_KEY: used = on_key(g, e->key, e->mods) ? 2 : 0; break;
    case FRG_FOCUS_LOST: focus_lost(g); break;
    default: used = 0; break;
    }
    return used | (used || memcmp(&before, &g->m, sizeof before) ? 1 : 0);
}

/* ---- the platform view's client */
static void cl_paint(void *ctx, frui_canvas *c, float scale)
{
    frp_gui_t *g = ctx;
    int d[4], y, newt;
    (void)scale;
    if (frp_gui_resize(g, c->w, c->h)) return;
    frp_gui_tick(g, mono_now());
    newt = c->px != g->tpx || c->w != g->tw || c->h != g->th;
    if (newt) g->full = 1;
    if (!frp_gui_paint(g, d) && !newt) return;
    if (newt) {                                      /* a new buffer: all of it, the margins dark */
        int x;
        for (y = 0; y < c->h; y++)
            for (x = 0; x < c->w; x++)
                if (x >= g->pw || y >= g->ph) c->px[(size_t)y * (size_t)c->w + (size_t)x] = 0xFF101012u;
        d[0] = 0; d[1] = 0; d[2] = g->pw; d[3] = g->ph;
        g->tpx = c->px; g->tw = c->w; g->th = c->h;
    }
    if (d[2] > c->w) d[2] = c->w;                    /* (a view smaller than the core's least canvas, 16 x 10) */
    if (d[3] > c->h) d[3] = c->h;
    for (y = d[1]; y < d[3] && d[2] > d[0]; y++)
        memcpy(c->px + (size_t)y * (size_t)c->w + (size_t)d[0], g->px + (size_t)y * (size_t)g->pw + (size_t)d[0],
               sizeof(uint32_t) * (size_t)(d[2] - d[0]));
}
static int cl_input(void *ctx, const frg_input *e) { return frp_gui_input(ctx, e); }
static int cl_tick(void *ctx) { return frp_gui_tick(ctx, mono_now()); }
const frg_client *frp_gui_client(frp_gui_t *g) { return &g->cl; }

/* ---- life */
frp_gui_t *frp_gui_new(const frp_ui_host_t *h)
{
    frp_gui_t *g;
    if (!s_refs) {
        s_font = frui_font_load(frp_font_text, (size_t)frp_font_text_len);
        s_dfont = frui_font_load(frp_font_display, (size_t)frp_font_display_len);
        if (!s_font || !s_dfont) {
            if (s_font) frui_font_free(s_font);
            if (s_dfont) frui_font_free(s_dfont);
            s_font = s_dfont = 0;
            return 0;
        }
    }
    g = calloc(1, sizeof *g);
    if (!g) return 0;
    g->h = *h;
    g->u = frui_new(s_font, g->h.text ? (frui_text_fn)g->h.text : frui_text_default, g->h.ctx);
    if (!g->u) { free(g); return 0; }
    s_refs++;
    frui_set_look(g->u, FRUI_LOOK_A3, s_dfont);     /* A3, the default look (the user's choice) */
    g->m.focus = g->m.hover = g->m.menu = g->m.ctx_knob = g->m.learning = -1;
    g->loc_learning = -1;
    g->wheel_id = -1;
    g->drag_note = -1;
    g->cl.ctx = g; g->cl.paint = cl_paint; g->cl.input = cl_input; g->cl.tick = cl_tick;
    g->loc_set[FRS_FIXVEL - FRS_CHANNEL] = 100;
    g->loc_set[FRS_PGM - FRS_CHANNEL] = 1;
    g->loc_set[FRS_BPM - FRS_CHANNEL] = 1200;
    g->loc_set[FRS_SYNCDIV - FRS_CHANNEL] = 6;
    g->lvl[0] = g->lvl[1] = g->pk[0] = g->pk[1] = -60.f;
    for (int i = 0; i < FRP_COUNT; i++) g->m.p[i] = frui_param_def[i];
    frp_gui_tick(g, 0.0);
    return g;
}
void frp_gui_free(frp_gui_t *g)
{
    int k;
    if (!g) return;
    focus_lost(g);
    for (k = 0; k < 128; k++) if (g->own_notes[k]) note(g, k, 0);   /* (a key held while the window closes) */
    frui_free(g->u);
    free(g->px);
    free(g->st);
    free(g);
    if (--s_refs == 0) {
        frui_font_free(s_font); frui_font_free(s_dfont);
        s_font = s_dfont = 0;
    }
}
